#[derive(Clone)]
struct matchwrapper{
	m:Vec<Vec<usize>>,
	w:Vec<Vec<usize>>,
	adj:Vec<Vec<[usize;2]>>,
	gsm:Vec<usize>,
	gsw:Vec<usize>,
	imggs:Vec<Pixbuf>,
	matches:Vec<Vec<usize>>,
	img:Vec<[Rc<RefCell<Pixbuf>>;2]>,
}
impl matchwrapper{
	fn new(m_pref:&Vec<Vec<usize>>,w_pref:&Vec<Vec<usize>>)->Self{
		let adj_=create_adj(&m_pref,&w_pref);
		/*
		let mut gsm_=gs::new2(&m_pref,&w_pref);
		gsm_.initialize_matches();
		gsm_.run();
		let mut gsw_=gs::new2(&w_pref,&m_pref);
		gsw_.initialize_matches();
		gsw_.run();
		let reshuffled_w=reshuffle_match_w2m(gsw_.matches);
		*/
		let ((x,y),(mut gs_m,mut gs_w),mut img_gs)=gs_wrapper(&m_pref,&w_pref);
		// !("WRAPPER: {:?}, {:?}",x,y);
		let mut pixb_vec:Vec<Pixbuf>=vec![];
		for i in 0..4{
			pixb_vec.push(img2pixbuf(&mut img_gs[i].clone()));
		}
		let mut imgm=create_res_img3(&x,adj_.clone(),0,0,0);
		let mut imgw=create_res_img3(&x,adj_.clone(),0,0,1);
		let pixm1=img2pixbuf(&mut imgm);
		let pixw1=img2pixbuf(&mut imgw);
		let mut imgm=create_res_img3(&y,adj_.clone(),0,0,0);
		let mut imgw=create_res_img3(&y,adj_.clone(),0,0,1);
		let pixm2=img2pixbuf(&mut imgm);
		let pixw2=img2pixbuf(&mut imgw);
		
		Self{
			m:m_pref.clone(),
			w:w_pref.clone(),
			adj:adj_.clone(),
			//gsm:gsm_.matches,
			gsm:x.clone(),
			//gsw:reshuffled_w,
			gsw:y.clone(),
			imggs:pixb_vec,
			matches:vec![x,y],
			img:vec![[Rc::new(RefCell::new(pixm1)),Rc::new(RefCell::new(pixw1))],[Rc::new(RefCell::new(pixm2)),Rc::new(RefCell::new(pixw2))]],
			//img:vec![],
		}
	}
	fn insert_match(&mut self,elem:&Vec<usize>){
		if *elem != self.gsm && *elem != self.gsw && !self.matches.contains(&elem){
			self.matches.push(elem.to_vec());
			let mut imgm=create_res_img3(&elem,self.adj.clone(),0,0,0);
			let mut imgw=create_res_img3(&elem,self.adj.clone(),0,0,1);
			let pixm=img2pixbuf(&mut imgm);
			let pixw=img2pixbuf(&mut imgw);
			self.img.push([Rc::new(RefCell::new(pixm)),Rc::new(RefCell::new(pixw))]);
		}
	}
	fn reset(&mut self,m:&Vec<Vec<usize>>,w:&Vec<Vec<usize>>,matches:&Vec<Vec<usize>>){
		let mut new:matchwrapper=matchwrapper::new(&m,&w);
		for i in 2..matches.len(){
			new.insert_match(&matches[i]);
		}
		//let mut gui:guiwrapper=guiwrapper::new();
		//gui.update(&new);
		// later! first: gui update!
		*self=new;
		
	}

	fn reset2(&mut self,input:&Vec<Vec<Vec<usize>>>){
		let m:Vec<Vec<usize>>=input[0].clone();
		let w:Vec<Vec<usize>>=input[1].clone();
		let mut matches:Vec<Vec<usize>>=vec![];
		if input.len()==3{
			matches=input[2].clone();
		}
		let mut new:matchwrapper=matchwrapper::new(&m,&w);
		if matches.len()>0{
			for i in 2..matches.len(){
				new.insert_match(&matches[i]);
			}
		}
		//let mut gui:guiwrapper=guiwrapper::new();
		//gui.update(&new);
		// later! first: gui update!
		*self=new;
		
	}

	//fn show_pref(&self,tvm:&mut TextView,tvw:&mut TextView)->(String,String){
	fn show_pref(&self)->(String,String){
		let mut txtm:String="Men Preferences\n\n".to_string();
		let mut txtw:String="Women Preferences\n\n".to_string();
		for i in 0..self.m.len(){
			txtm+=&format!("{:?}\n",self.m[i]);
			txtw+=&format!("{:?}\n",self.w[i]);			
		}
		//tvm.buffer().expect("TextBuffer m in matchwrapper").set_text(&txtm);
		//tvw.buffer().expect("TextBuffer w in matchwrapper").set_text(&txtw);
		(txtm,txtw)
	}
	fn show_matches(&self)->String{
		insert_textbuffer(&self.matches)
	}
	fn save_project(&self,pathname:&str){
		let mut path:&str=&pathname.replace("\"","");
		let mpath:&str=&(path.to_owned()+"/m.txt").to_string();
		let wpath:&str=&(path.to_owned()+"/w.txt");
		let matchespath:&str=&(path.to_owned()+"/matches.txt");
		write_file(&self.m,mpath.to_string());
		write_file(&self.w,wpath.to_string());
		write_file(&self.matches,matchespath.to_string());
	}
	//fn load_project_from_folder(&mut self,path:&str)->Option<String>{
	//fn check_files(&mut self,path:&str)->Option<String>{
	fn check_files(&mut self,path:&str)->(Option<[Vec<Vec<usize>>;3]>,Option<String>){
		//let mut error:Option<&str>=None;
		let mut error:Option<String>=None;
		let mut input:[Vec<Vec<usize>>;3]=[vec![],vec![],vec![]];
		let files:[&str;3]=["m.txt","w.txt","matches.txt"];
		let mut filespath:Vec<String>=vec![];
		let mut errfiles:Vec<usize>=vec![];
		//let mut path_rpl:&str=path;
		let path_rpl:&str=&path.replace("\"","");
		// !("check_files!");
		for i in 0..files.len(){
			let path_i:&str=&(path_rpl.to_owned()+"/"+files[i]);
			filespath.push(path_i.to_string());
			//println!("path_i: {:?}",path_i);
			if !Path::exists(Path::new(path_i)){
				errfiles.push(i);
			}	
		}
		let mut erradd:String="Files not found:\n\n".to_string();
		for i in 0..errfiles.len(){
			erradd+=&(files[errfiles[i]]);
		}
		if errfiles.len()>0{
			error=Some(erradd.to_string());
		}
		// errfiles.len()==0
		else{
			for i in 0..filespath.len(){
				//let file=File::open(Path::new(&filespath[i]));
				let chcktxt:String=fs::read_to_string(filespath[i].clone()).expect("Reading from filespath failed");
				let (param,errchck)=check_welldefined(&chcktxt);
				if errchck.is_some(){
					error=Some(errchck.expect("Input data not well-defined!").to_string());
					break;
				}
				else{
					input[i]=param.expect("Error in check_files()!");
				}
			}
		}
		let mut ret_input:Option<[Vec<Vec<usize>>;3]>=None;
		if !error.is_some(){
			ret_input=Some(input);
		}
		(ret_input,error)
	}
	
	
	
	
	
	fn check_files2(&self,path:&str)->(Option<Vec<Vec<Vec<usize>>>>,Option<String>){
		let mut input:Vec<Vec<Vec<usize>>>=vec![];
		let mut error:Option<String>=None;
		let files:[&str;3]=["m.txt","w.txt","matches.txt"];
		let mut filespath:Vec<String>=vec![];
		let mut errfiles:Vec<usize>=vec![];
		//let mut path_rpl:&str=path;
		let path_rpl:&str=&path.replace("\"","");
		// !("check_files!");
		for i in 0..files.len(){
			let path_i:&str=&(path_rpl.to_owned()+"/"+files[i]);
			filespath.push(path_i.to_string());
			//println!("path_i: {:?}",path_i);
			if !Path::exists(Path::new(path_i)){
				errfiles.push(i);
			}	
		}
		let mut erradd:String="Files not found:\n\n".to_string();
		for i in 0..errfiles.len(){
			erradd+=&(files[errfiles[i]]);
		}
		if errfiles.len()>0 && (errfiles.contains(&0) || errfiles.contains(&1)){
			//println!("matches.txt available?");
			if errfiles.contains(&0) || errfiles.contains(&1){
				error=Some(erradd.to_string());
			}
		}
		else{
			for i in 0..filespath.len(){
				if !errfiles.contains(&i){
				//let file=File::open(Path::new(&filespath[i]));
				let chcktxt:String=fs::read_to_string(filespath[i].clone()).expect("Reading from filespath failed");
				let (param,errchck)=check_welldefined(&chcktxt);
				if errchck.is_some(){
					error=Some(errchck.expect("Input data not well-defined!").to_string());
					break;
				}
				else{
					//input[i]=param.expect("Error in check_files()!");
					input.push(param.expect("Error in check_files()!"));
				}
				}
			}			
		}
		//let mut ret_input:Option<[Vec<Vec<usize>>;3]>=None;
		let mut ret_input:Option<Vec<Vec<Vec<usize>>>>=None;
		if !error.is_some(){
			ret_input=Some(input);
		}
		(ret_input,error)	}
	
	//fn load_project_from_folder(&mut self,path:&str)->Option<String>{
	fn load_project_from_folder(&mut self,path:&str,gui:Rc<RefCell<guiwrapper>>)->Option<String>{
	//fn load_project_from_folder(&mut self,path:&str){
		// !("load project!");
		let mut ret_err:Option<String>=None;
		let (mut input,error)=self.check_files2(&path);
		if !error.is_some(){
			//println!("input: {:?}",input);
			//let mut fn_input:[Vec<Vec<usize>>;3]=input.as_mut().expect("").clone();
			let mut fn_input:Vec<Vec<Vec<usize>>>=input.as_mut().expect("").to_vec();
			//self.reset(&fn_input[0],&fn_input[1],&fn_input[2]);
			self.reset2(&fn_input);
			gui.borrow_mut().update(Rc::new(RefCell::new(self.clone())));
		}
		else{
			ret_err=error.clone();
			//println!("error in load project: {:?}",error.clone());
		}
		ret_err
	}
}




//fn check_welldefined(txt:&String)->(Option<Vec<Vec<usize>>>,Option<String>){
fn check_welldefined(txt:&String)->(Option<Vec<Vec<usize>>>,Option<&str>){
	//let pattern:[&str;2]=["[","]"];
	//let pattern:[char;2]=['[',']'];
	// !("txt: {:?}",txt);
	let mut txt_vec:Vec<&str>=txt.split('\n').collect();
	let mut n:usize=txt_vec.len();
	let mut txti_vec:Vec<Vec<&str>>=vec![];
	let mut usize_vec:Vec<Vec<usize>>=vec![];
	//let mut error:&str="";
	let mut error:Option<&str>=None;
	for i in 0..txt_vec.len(){
		let mut txti:Vec<&str>=txt_vec[i].split(',').collect();
		//println!("txti.len()={}",txti.len());
		let mut uvec:Vec<usize>=vec![];
		if txti.len()>0{
			for j in 0..txti.len(){
				txti[j].replace("[","");
				txti[j].replace("]","");
				let elem:Vec<&str>=txti[j].split_whitespace().collect();
				if elem.len()>1{
					//error="Big Problem!";
					error=Some("Big Problem!\nMaybe you forgot a comma?");
					//error=Some(&format!("Big Problem!\nMaybe you forgot a comma in line {}?",(i+1)) as &str);
					break;
				}
				else{
					//txti[j].replace(" ","");
					let txtij=txti[j].replace(" ","").replace("[","").replace("]","");
					//println!("txtij: {:?}",txtij);
					if txtij.len()>0{
					//uvec.push(str_num2(txti[j].to_string()));
					//uvec.push(str_num2(txtij.to_string()));
					uvec.push(txtij.parse().expect("Not a valid number"));
					}
				}
				//println!("uvec: {:?}",uvec);
			}
		}
		//if error!=""{
		if error.is_some(){
			break;
		}
		if uvec.len()>0{
			usize_vec.push(uvec);
		}
	}
	let mut res:Option<Vec<Vec<usize>>>=None;
	if !error.is_some(){
		//let ntmp=usize_vec.len();
		let ntmp=usize_vec[0].len();
		
		let mut pat:Vec<usize>=vec![];
		for i in 0..ntmp{
			pat.push(i);
		}
		for i in 0..usize_vec.len(){
			// !("usize_vec: {:?}",usize_vec);
			if usize_vec[i].len()!=ntmp{
				error=Some("Different amounts of values!");
			}
			else{
				let mut tmp:Vec<usize>=pat.clone();
				for j in 0..usize_vec[i].len(){
					if tmp.contains(&usize_vec[i][j]){
						let pos:usize=tmp.iter().position(|x| *x==usize_vec[i][j]).expect("");
						tmp.remove(pos);
					}
					else{
						error=Some("Double or missing values?");
						break;
					}
				}
			}
			if error.is_some(){
				break;
			}
		}
		
		
		if !error.is_some(){
			res=Some(usize_vec);
		}
	}
	// !("return: {:?}",(res.clone(),error));
	//(None,None)
	(res,error)
}

fn insert_treeview(tree:&mut ListStore,entry:&Vec<usize>,wrapper:Rc<RefCell<matchwrapper>>,gs_val:usize){
	tree.clear();
	let gs_string:[String;3]=["men-optimal".to_string(),"women-optimal".to_string(),"".to_string()];
	let wr:matchwrapper=wrapper.borrow_mut().clone();
	let matches=&wr.matches;
	let adj=&wr.adj;
	for i in 0..matches.len(){
		//let wfc=calc_wf(&wrapper.borrow_mut().adj,&entry);
		let wfc=calc_wf(&adj,&matches[i]);
		let mut value=format_wf(wfc.clone());
		value.insert(0,"i".to_string());
		let mut value_7th=&"".to_string();
		if i<2{
			value_7th=&gs_string[i];
		}
		tree.insert_with_values(/*Some(-1)*/None, &[(0,&i.to_string()), //&value[0].to_string()),
			(1,&value[1].to_string()),
			(2,&value[2].to_string()),
			(3,&value[3].to_string()),
			(4,&value[4].to_string()),
			(5,&value[5].to_string()),
			(6,&value[6].to_string()),
			//(7,&value[7].to_string())
			//(7,&gs_string[gs_val])
			(7,&value_7th)
		]);
	}
}
fn insert_textbuffer(matches:&Vec<Vec<usize>>)->String{
	let mut outp_str = "Matches:\n\n".to_string();
	let n:usize=matches[0].len();
	let mut reg_vec:Vec<usize>=vec![];
	for i in 0..n{
		reg_vec.push(i);
	}
	outp_str+=&format!("{:?}\n",reg_vec);
	let dig:String="=".to_string();
	for i in 0..n{
			outp_str+=&dig;
			outp_str+=&dig;							
		if i>10{
			outp_str+=&dig;
		}
		if i>100{
			outp_str+=&dig;							
		}
	}
	outp_str+="\n";
	let gs_string=[&"\tmen-optimal".to_string(),&"\twomen-optimal".to_string()];
	//outp_str+=&format!("{:?}\n",gsm).to_string();
	//outp_str+=&format!("{:?}\n",gsw).to_string();
	for i in 0..matches.len(){
		outp_str+=&format!("{:?}",matches[i]).to_string();
		if i<2{
			outp_str+=gs_string[i];
		}
		outp_str+=&"\n".to_string();
	}
	outp_str
}



