fn vec_string(a:&Vec<usize>)->String{
	let res = format!("[{}]\n", a.iter()
		.map(|&x| x.to_string())
		.collect::<Vec<String>>().join(", "));
	return res;
}



fn write_file(a:&Vec<Vec<usize>>,path:String){
	let mut fs = File::create(path);
	let mut txt = String::new();
	for i in 0..a.len() {
		txt+=&vec_string(&a[i]);
	}

	fs.expect("Problem with the file!").write_all(txt.as_bytes());
}

// create one inverted preference matrix of two sets of agents
fn create_adj( m_: &Vec<Vec<usize>>, w_: &Vec<Vec<usize>> ) -> Vec<Vec<[usize; 2]>> {
	let mut adj = vec![];
	let l = m_.len();
	for i in 0..m_.len() {
		adj.push( vec![] );
		for j in 0..m_.len() {
			adj[i].push([l,l]);
		}
	}
	for i in 0..l {
		for j in 0..m_.len() {
			let mij = m_[i][j];
			let wij = w_[i][j];
			let posmw = m_[i].iter().position(|&x| x == mij).unwrap();
			let poswm = w_[i].iter().position(|&x| x == wij).unwrap();
			adj[i][mij][0] = posmw;
			adj[wij][i][1] = poswm;
		}
	}
	return adj;
}

struct gs {
	m: Vec<Vec<usize>>,
	w: Vec<Vec<usize>>,
	matches: Vec<usize>,
	compl:bool
}
impl gs {
	fn new(m_:&Vec<Vec<usize>>, w_:&Vec<Vec<usize>>, matches_:&Vec<usize>, compl_:bool) -> Self {
		Self {
			m: m_.to_vec(),
			w: w_.to_vec(),
			matches: matches_.to_vec(),
			compl:compl_
		}
	}
	fn new2(m_:&Vec<Vec<usize>>, w_:&Vec<Vec<usize>>) -> Self {
		Self {
			m: m_.to_vec(),
			w: w_.to_vec(),
			matches: vec![],
			compl:false
		}		
	}	
	// for puishing i, the header has to include &mut !
	fn initialize_matches(&mut self){
		let n: usize = self.m.len();
		self.matches=vec![];
		for i in 0..n {
			let mut idx:usize= i as usize;
			//self.matches.push(idx);
			self.matches.push(n);
		}
		//println!("init: {:?}", self.matches);
	}
	
	fn empty_match(&self)->bool{
		let mut empty:bool=false;
		for i in 0..self.matches.len(){
			if self.matches[i]!=self.matches.len(){
				empty=true;
				break;
			}
		}
		return empty;
	}
	fn next_w(&self, mid:usize, wid:usize)->usize{
		//println!("next mid{}, wid{}", mid,wid);
		let mut wpos:usize=self.m[mid].iter().position(|&x| x==wid).unwrap();
		if wpos<self.m.len()-1{
			wpos+=1;
		}
		else{
			//println!("wpos at end");
		}
		return self.m[mid][wpos];
	}
	fn accept(&mut self,wid:usize,mid:usize)->bool{
		let n:usize = self.m.len();
		//println!("accept wid{} mid{}",wid,mid);
		let mut acc:bool=false;
		//if !self.compl{
			if self.matches.contains(&wid){
				let mut m_old:usize=self.matches.iter().position(|&x| x==wid).unwrap();
				//println!("m_old {}, mid {} wid {}", m_old, mid, wid);
				if m_old != mid {
					if self.w[wid].iter().position(|&x| x==mid).unwrap() < self.w[wid].iter().position(|&x| x==m_old).unwrap(){
						//acc=true;
						self.matches[mid]=wid;
						self.matches[m_old]=n;
						self.propose2(m_old,wid);

						if !self.matches.contains(&n){
							self.compl=true;
						}

						return true;
					}
					else{
						//acc=false;
						return false;
					}
				}
				else {
					// be careful
					if self.matches[m_old] != wid{
						//acc=false;
						return false;
					}
					else{
						//acc=true;
						return true;
					}
					/*
					if self.matches[mid]==wid {
						acc = true;
						if !self.matches.contains(&n) {
							self.compl = true;
						}
					}
					else{
						acc=false;
					}
					*/

				}
			}
			else {
				self.matches[mid]=wid;
				//acc=true;
				if !self.matches.contains(&n){
					self.compl=true;
				}
				return true;
			}
		//}
		//acc=true;
		//println!("acc: {} match: {:?}", acc, self.matches);
		//return acc;
	}	

	fn propose2(&mut self,id:usize, w_id:usize){
		let mut accepted:bool=self.accept(w_id,id);
		//if self.accept(w_id,id){
		if accepted{
			//self.matches[id]=w_id;
		}
		else{
			let mut p_id:usize=0;
				let next:usize=self.next_w(id,w_id);			
				//println!("while propose p_id {} wid {}, id {}", p_id, w_id, id);
				self.propose2(id,next);
				p_id+=1;
				//accepted=self.accept(next,id);
		}
	}

	
	
	fn run(&mut self) {
		let n:usize=self.m.len();
		let mut r_id:usize=0;
		while self.matches.contains(&n) && !self.compl{
			//dbg!("while r_id {}, run {:?}", r_id, &self.matches);
			for i in 0..self.m.len() {
				//if self.matches.contains(&n) {
				if !self.compl{
					self.propose2(i,self.m[i][0]);
				}
				else{
					break;
				}
			}
			r_id+=1;
		}
		
		
		
		//dbg!("gs match: {:?}", &self.matches);
	}
	
	
	// run with widget
	fn run2(&mut self, progressbar: &mut ProgressBar) {
		let n:usize=self.m.len();
		let mut r_id:usize=0;
		while self.matches.contains(&n) && !self.compl{
			//dbg!("while r_id {}, run {:?}", r_id, &self.matches);
			for i in 0..self.m.len() {
				//if self.matches.contains(&n) {
				if !self.compl{
					self.propose2(i,self.m[i][0]);
				}
				else{
					break;
				}
				let mut frac = (i+1) as f64 / n as f64;
				// !("progressbar {}",frac);
				progressbar.set_fraction(frac); 
			}
			r_id+=1;
		}
		
		
		
		//dbg!("gs match: {:?}", &self.matches);
	}

	
	fn print_gs_match(&self){
		
	}
}


