	fn show_matches(&self){
		
	}
    
    
    
    // main function of algorithm
    fn update_list(&mut self) {
    	let k = self.kfind().clone();
    	let len = self.m.len();
    	let mut idx: usize = 0;
    	while k[idx].len() == 0 {
    		idx+=1;
    	}
    	let mut list: Vec<Vec<usize>> = vec![];
    	let mut list_i: Vec<usize> = vec![0;len];
    	let k_add:usize = self.get_first_k();
    	list_i.fill(len);
    	list_i[k[idx][0][0]] = k[idx][0][1];
    	list.push(list_i.clone());
		let mut l: usize = 0;
    		
    	for i in idx..k.len() {
			let mut moveon: bool = true;
    		let mut jloop_end = false;
    		for j in 0..k[i].len() {
    		
    		let mut l = 0;
    		while l < list.len() {
    			let mut removed: bool = false;
    			if !(i == idx && j == 0) {
						let mut put: bool = false;
						let mut m: usize = k[i][j][0];
						let mut w: usize = k[i][j][1];
						
						if list[l].iter().filter(|&x| *x==len).count() > 0 {
							let mut line: Vec<usize> = list[l].clone();
							let mut both1 = false;
							let mut both2 = false;
							if line.iter().filter(|&x| *x == w).count() > 0 {
								let mut pos = line.iter().position( |&x| x == w).unwrap();
								line[pos] = len; //
								put = true;
								both2 = true;
							}
							if line[m] != len {
								line[m] = len;
								put = true;
								both1 = true;
							}
							
							if both1 && both2 {
							}
							let mut bpbool = false;
							for n in 0..len {
								if line[n] != len {
									let bp: Vec<[usize;2]> = self.bpfind(&[m,w],&[n,line[n]]);
									for o in 0..bp.len() {
										line[bp[o][0]] = len;
										if line.iter().filter(|&x| *x==bp[o][1]).count() > 0 {
											let mut bppos = line.iter().position(|&x| x==bp[o][1]).unwrap();
											line[bppos]=len;
										}
										bpbool = true;
									}
								}			
							}				
							if line == list[l] {
								list[l][m] = w;
								if list[l].iter().filter(|&x| *x==len).count() == 0 {
									self.matches.push(list[l].clone());
									let wf = self.calc_wf(&list[l]);
								}
							}
							else {
								line[m] = w;
								let mut in_list: bool = false;
								let mut check_in_idx = l;
								check_in_idx += 1;
								for n in 0..list.len() {
									if self.check_lines(&list[n], &line) == true {
										in_list = true;
										list[n] = line.clone();
										break;
									}
								}
								if in_list == false {
									list.push(line.clone());
								}
							}													
						}
					}
	    		if j == k[i].len()-1 {
	    			jloop_end = true;
	    		}
				let k_add = self.get_first_k();
				let len_del = self.m.len();
				//list = self.sort_longest_chains(&list.clone(), len_del-i+2);
				list=self.sort_adj_welfare(&list.clone(),self.diff);
				l+=1;
				}    		
    		}
    	}
    	let mut new = self.delete_incomplete(&list);
    	let mut new1: Vec<Vec<usize>> = vec![]; 
    	for i in 0..new.len() {
    		if !new1.contains(&new[i]) {
    			new1.push(new[i].clone());
    			let mut wf: [f64;6] = self.calc_wf(&new[i]);
    		}
    	}
    }

    // output of matches
    fn print_matches(&self) {
    	for i in 0..self.matches.len() {
			let wf = self.calc_wf(&self.matches[i]);
			// !("match: {:?}", &self.matches[i]);
    	}
    	//println!("\n\nMatches total: {}", self.matches.len());
    }
    
    fn save_matches(&self){
		write_file(&self.matches,"Matches.txt".to_string());
	}
	
	fn import_gs(&mut self, men:Vec<usize>,women:Vec<usize>){
		self.gs_men=men;
		self.gs_women=women;
	}
    
    // calculate the overall wellfare, equality ratio and the adjusted overall wellfare
    fn calc_wf(&self, list: &Vec<usize>) -> [f64;6] {
    	let mut mwell: f64 = 0.0;
    	let mut wwell: f64 = 0.0;
    	let len: usize = self.m.len();
    	let max: f64 = 2.0 * len.pow(2) as f64;
    	for i in 0..list.len() {
    		let mut w: usize = list[i];
    		mwell += len as f64 - self.adj[i][w][0] as f64;
    		wwell += len as f64 - self.adj[i][w][1] as f64;    		
    	}
    	let wf=mwell+wwell;
    	let m_ratio=mwell/wf;
    	let corr_f = 1.0/(1.0+(m_ratio-0.5).abs());
    	return [mwell,wwell,wf,m_ratio,corr_f*wf,wf/max];
    }
    
    fn format_wf(&self,wf:[f64;6])->Vec<String>{
			// !("wf func: {:?}", wf);
			let mut res:Vec<String>=vec![];
			res.push(wf[2].to_string());
			res.push(wf[0].to_string());
			res.push(wf[1].to_string());
			let mut eq:String=format!("{:.2}",wf[3]*100.0);
			eq += &" %".to_string();
			res.push(eq);
			let nw:String=format!("{:.2}", wf[4]);
			res.push(nw);
			let mut sat:String=format!("{:.2}",wf[5]*100.0);
			sat += &" %".to_string();
			res.push(sat);
			/*
			for i in 3..wf.len(){	
				let fst:String= format!("{:.2}",wf[i]);
				res.push(fst);
			}
			*/
			//println!("format wf: {:?}", res);
			return res;
	}
	
