fn create_res_img4(match_:&Vec<usize>,adj:Vec<Vec<[usize;2]>>,gs_:usize,opt:usize,gend:usize, w_:usize,h_:usize)->RgbImage{
	let n = adj.len();
	let gender = gend;
	let col = Rgb([240, 24, 90]);
	let w:u32= w_ as u32; //100;
	let h:u32= h_ as u32; //100;
	let div_w: f64 = w as f64 / n as f64;
	let div_h: f64 = h as f64 / n as f64;
	let new_w: f64 = n as f64 * div_w;
	let new_h: f64 = n as f64 * div_h;
	let pw = div_w as usize;
	let ph = div_h as usize;
	let new_width = (n * pw) as u32;
	let new_height = (n * ph) as u32;
	let mut img: RgbImage=RgbImage::new(new_width,new_height);
	img = fill_pic(&img);
	let color= Rgba([180, 20, 70, 80]);

	
	if gender == 0 {
	if match_.len() != 0 {
		for j in 0..n {
			for k in 0..ph{
				for m in 0..pw{
					let x = (ph * j + k) as u32;
					let mut adj_m:usize=0;
					
					let adj_m = adj[j][match_[j]][gender];
					
					let y = (pw * adj_m + m) as u32;
					img.put_pixel(y,x,col);
				}
			}
		}	
	}
	}

	if gender == 1{
	
	if match_.len() != 0 {
		for j in 0..n {
			for k in 0..ph{
				for m in 0..pw{
					let x = (ph * match_[j] + k) as u32;
					let mut adj_m:usize=0;
					let adj_m = adj[j][match_[j]][gender];
					let y = (pw * adj_m + m) as u32;
					img.put_pixel(y,x,col);
				}
			}
		}	
	}
	
	}	
	let rgbimg= RgbImage::new(w,h);
	let new2 = fill_pic(&rgbimg);
	let pathname:String=get_save_name(gs_,opt,gender);
	
	/*
	if gender == 0 {
		if !gs{
			img.save("Matching_Men.jpg");
		}
		else{
			img.save("GS_Matching_Men.jpg");
		}
	}
	if gender == 1 {
		if !gs{
			img.save("Matching_Women.jpg");
		}
		else{
			img.save("GS_Matching_Women.jpg");			
		}
	}
	*/
	//img.save(pathname);
	return img;
}


fn get_save_name(gs_:usize,opt:usize,gender:usize)->String{
	let mut txt:String="".to_string();
	if gs_==1{
		txt+=&"GS_".to_string();
		if opt==0{
			txt+=&"men_optimal_".to_string();
		}
		else{
			txt+=&"women_optimal_".to_string();
		}
	}
	txt+=&"Matching_".to_string();
	if gender==0{
		txt+=&"Men.".to_string();
	}
	else{
		txt+=&"Women.".to_string();
	}
	txt+=&"png".to_string();
	//println!("GET SAVE NAME: {:?}",txt);
	return txt;
}

fn check_doubles(res:Vec<usize>)->bool{
	let mut doubles:Vec<[usize;2]>=vec![];
	let mut is_doubled:bool=false;
	for i in 0..res.len(){
		if res.iter().filter(|&x| *x==res[i]).count() > 1{
			doubles.push([i,res[i]]);
			is_doubled=true;
		}
	}
	// !("\n\nWARNING!!!\nGS DOUBLES !!!!: {:?}\n", doubles);
	return is_doubled;
}

fn calc(n_:usize)->[usize;2]{
	let mut d:usize	=0;
	let mut b:usize=20;
	let n: usize = n_;
	if n < 5 {
		d=0;
		b=200;
	}
	else if n < 10 {
		d=0;
		b=150;
	}
	else if n<15 {
		d=3;
		b=30;
	}
	else if n < 50 {
		d=(0.2 * n as f64) as usize;
		b=25;
	}
	else if n < 120{
		d=(0.3 * n as f64) as usize;
		b=20;		
	}
	else if n < 250{
		d=(0.5 * n as f64) as usize;
		b=15;		
	}
	else if n < 400{
		d=(0.7 * n as f64) as usize;
		b=15;		
	}
	else if n < 700{
		d=(0.8 * n as f64) as usize;
		b=10;		
	}
	else if n < 1000{
		d=(0.9 * n as f64) as usize;
		b=12;		
	}
	else {
		d=(1.0 * n as f64) as usize;
		b=8;		
	}

	return [d,b];
}

fn bp_matrix(adj:&Vec<Vec<[usize;2]>>)->Vec<Vec<bool>>{
	let mut mat:Vec<Vec<bool>>=vec![];
	let n:usize=adj.len();
	//for i in 0..n*n{
	for i in 0..n{		
		// !("bp_matrix i:{}, len:{}",i,adj.len());
		//for j in 0..i{
		for j in 0..n{
			let mut row:Vec<bool>=vec![];
			//let mut idx:usize=i*n+j;
			for k in 0..n{
				for m in 0..n{
					/*
					let mut idx_2:usize=k*n+m;
					if idx_2<idx{
						
					}
					*/
					// BE VERY CAREFUL!!!!!!!
					//if i!=k && j!=m{
					
					//if !(i==k && j==m){
					if !(i==k || j==m){
						if !bp_efficient(&adj,&[i,j],&[k,m],0){
							row.push(true);
						}
						else{
							row.push(false);
						}
					}
					else{
						row.push(false);
					}					
				}
			}
			mat.push(row);			
		}
	}
	mat
}

