fn get_id_from_num(num:usize,bs:usize)->Vec<usize>{
	let mut new:Vec<usize>=vec![];
	//let num:usize=31;
	//let raw=BitVec::from_element(7_usize);
	let raw = num.view_bits::<Lsb0>();
	//println!("RAW {:?}",raw);
	let len:usize=raw.len();
	
	//println!("BIT VEC: {:?}",bp_matrix_2usize(&bp_matrix));
	//println!("BIT VEC BLOCK: {:?}",bp_matrix_2usize_block(&bp_matrix,5));
	
	
	//println!("TEST LARGE NUMBERS BIT: {}", 340282366920938463463374600121768211455 as u128 & 20000000000000000000000 as u128);
	
	//340282366920938463463374607431768211455
	
	
	
	//let bits=raw.iter_ones().position(|x| x==1).unwrap();
	let bits=raw.iter_ones();//.filter(|x| *x==1);
	//println!("BITS ITER {:?}",bits);
	
	//println!("TEST BIT ITER: {}",raw.len());
	//println!("TEST RAW ITER ONES: {:?}",raw.iter_ones().rev());
	for bit in raw.iter_ones().rev(){
		//print
		//println!("bit: {}, bs: {} ",bit,bs);
		//new.push(len-bit);
		
		new.push(bs-bit-1);
	}
	//println!();
	//println!("GET ID NEW: {:?}",new);
	new
}

fn transform_sync2reg_match(matchres:&Vec<usize>,order:&Vec<usize>)->Vec<usize>{
	// !("TRANSF SYNC2REG matchres: {:?}, order: {:?}",matchres,order);
	let mut new:Vec<usize>=vec![];
	let n:usize=matchres.len();
	//for i in 0..order.len(){
	//println!("match: {:?}\norder: {:?}",matchres,order); 
	for i in 0..n{
		new.push(order[matchres[i]]);
	}
	//println!("NEW TRANSF: {:?}",new);
	let decomposed:Vec<[usize;2]>=decompose_compl(&new,n);
	//println!("DECOMP: {:?}",decomposed);
	let mut line:Vec<usize>=vec![];
	for i in 0..n{
		for j in 0..n{
			if decomposed[j][0]==i{
				line.push(decomposed[j][1]);
				break;
			}
		}
	}
	//println!("line: {:?}",line);
	line
}



fn decompose_compl(row:&Vec<usize>,n:usize)->Vec<[usize;2]>{
	let mut compl:Vec<[usize;2]>=vec![];
	//let n:usize=row.len().isqrt();
	for i in 0..row.len(){
		let (k,m)=decompose_ij(row[i],n);
		compl.push([k,m]);
	}
	compl
}

fn decompose_ij(len:usize,n:usize)->(usize,usize){
	let mut i:usize=len/n;
	let mut j:usize=len-i*n;
	//println!("len: {}, n: {}, i: {}, j: {}",len,n,i,j);
	(i,j)
}



// calculate the overall wellfare, equality ratio and the adjusted overall wellfare
fn calc_wf(adj:&Vec<Vec<[usize;2]>>,list: &Vec<usize>) -> [f64;6] {
	let mut mwell: f64 = 0.0;
	let mut wwell: f64 = 0.0;
	let len: usize = adj.len();
	let max: f64 = 2.0 * len.pow(2) as f64;
	for i in 0..list.len() {
		let mut w: usize = list[i];
		mwell += len as f64 - adj[i][w][0] as f64;
		wwell += len as f64 - adj[i][w][1] as f64;    		
	}
	let wf=mwell+wwell;
	let m_ratio=mwell/wf;
	let corr_f = 1.0/(1.0+(m_ratio-0.5).abs());
	return [mwell,wwell,wf,m_ratio,corr_f*wf,wf/max];
}

fn format_wf(wf:[f64;6])->Vec<String>{
		// !("wf func: {:?}", wf);
		let mut res:Vec<String>=vec![];
		res.push(wf[2].to_string());
		res.push(wf[0].to_string());
		res.push(wf[1].to_string());
		let mut eq:String=format!("{:.2}",wf[3]*100.0);
		eq += &" %".to_string();
		res.push(eq);
		let nw:String=format!("{:.2}", wf[4]);
		res.push(nw);
		let mut sat:String=format!("{:.2}",wf[5]*100.0);
		sat += &" %".to_string();
		res.push(sat);
		/*
		for i in 3..wf.len(){	
			let fst:String= format!("{:.2}",wf[i]);
			res.push(fst);
		}
		*/
		//println!("format wf: {:?}", res);
		return res;
}




