fn reshuffle_match_w2m(w_match:Vec<usize>)->Vec<usize>{
	let mut m_match:Vec<usize>=vec![];
	//println!("reshuffle w2m {:?}", w_match);
	for i in 0..w_match.len(){
		let w_id=w_match.iter().position(|&x| x==i).unwrap();
		m_match.push(w_id);
	}
	return m_match;
}


