// PREPARATION VEC-STRING FOR INSERTION INTO TREEVIEW !!!!!!!

fn insert_into_treeview(matching_:matching, list:Vec<usize>, m_pref:Vec<Vec<usize>>, w_pref:Vec<Vec<usize>>, gale_bool:bool, gend:usize, id:usize) -> Vec<String>{

	// !("insert into treeview fn");

	let mut k_matches:Vec<Vec<usize>> = vec![];
	let mut adj = create_adj( &m_pref, &w_pref );
	let mut k_list: Vec<Vec<usize>> = vec![];
	let mut kset: Vec<Vec<[usize;2]>> = vec![];
	let mut diff:usize=20;
	let mut batch:usize=50;
	
	let mut mat = matching::new(
		&m_pref,&w_pref,&adj,&k_list,&kset,&k_matches,
		diff, batch, vec![], vec![]);

		
	let wfc = mat.calc_wf(&list);
	let wf = mat.format_wf(wfc);
		
	//println!("wf: {:?}", wf);
	// eventhandler!
	let bp_cnt=mat.count_bp(&list);
	//println!("matches: \n{:?}\nwf:\n{:?}\nbp_cnt\n{:?}\n", list,wf,bp_cnt);
	let id = mat.matches.len();
	let mut gale:String="".to_string();

	let mut message:Vec<String>=vec![];
	//model_clone.insert_with_values(Some(0), &[
	//println!("message {:?} mat.matches {:?}", message, mat.matches);
	
	
	// BE CAREFUL !!!!!!! THINK OF SHIFT OF ENTRIES !!!!!!!
	//message.push((mat.matches.len()-1).to_string());
	message.push((id).to_string());	
	
	for wf_id in wf {
		message.push(wf_id.to_string());
	}
	//println!("message vor list[i] {:?}", message);
	//println!("l {} list.len {}", l, list.len());
	//println!("gs {:?},\nlist[i] {:?}", mat.gs_men, list[l]);
	if gend == 0 {
		message.push("men-optimal".to_string())
	}
	else if gend == 1 {
		message.push("women-optimal".to_string());
	}
	if gend == 2 {
		//be careful !!!!
		//println!("BOTH !!!! {:?}", message);
		message.pop();
		message.push("men and women-optimal".to_string());
		
	}									
	//println!("message: {:?}", message);
	
	let mut match_data:Vec<String>=vec![];	
	
	
	//println!("MATCH_DATA BEFORE INSERTING: {:?}", match_data);
	//return match_data
	return message;
	
}











